export type IconName = keyof typeof LucideIcons | keyof typeof customIcons;

interface IconProps {
    name: IconName;
    size?: number;
    color?: string;
    className?: string;
    fill?: string,
}

const Icon: React.FC<IconProps> = ({
    name,
    size = 24,
    color = "currentColor",
    className = "",
    ...props
}) => {
    const LucideIcon = (LucideIcons as any)[name];
    const CustomIcon = (customIcons as Record<string, React.FC<React.SVGProps<SVGSVGElement>>>)[name];

    if (LucideIcon) {
        return <LucideIcon size={size} color={color} className={className} {...props} />;
    }

    if (CustomIcon) {
        return <CustomIcon width={size} height={size} fill={color} className={className} {...props} />;
    }

    console.warn(`Icon "${name}" not found.`);
    return null;
};

export default Icon;
